mapper.select:
/* TbmSessionShareMapper.countMyAttendance */
SELECT COUNT(1)
FROM TB_TBM_ATTENDANCE AT
WHERE AT.SESSION_CD = #{sessionCd}
  AND AT.CMPNY_CD = #{cmpnyCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
  AND AT.DEL_YN = 'N'

/* TbmSessionShareMapper.selectTier1CmpnyList */
SELECT
      S.SHARE_CMPNY_CD          AS cmpnyCd
    , IFNULL(C.CMPNY_NM, '')    AS cmpnyNm
FROM TB_TBM_SESSION_SHARE S
     LEFT OUTER JOIN TB_CMPNY C
        ON (
            C.CMPNY_CD = S.SHARE_CMPNY_CD
        )
WHERE S.SESSION_CD = #{sessionCd}
  AND S.DESIGNATED_BY_CMPNY_CD = #{hostCmpnyCd}
  AND S.DEL_YN = 'N'
ORDER BY cmpnyNm ASC

/* TbmSessionShareMapper.countTier1Designation */
SELECT COUNT(1)
FROM TB_TBM_SESSION_SHARE S
WHERE S.SESSION_CD = #{sessionCd}
  AND S.DESIGNATED_BY_CMPNY_CD = #{hostCmpnyCd}
  AND S.SHARE_CMPNY_CD = #{shareCmpnyCd}
  AND S.DEL_YN = 'N'

/* TbmSessionShareMapper.selectParentCmpnyNmBySessions */
SELECT
      S.SESSION_CD              AS sessionCd
    , IFNULL(C.CMPNY_NM, '')    AS hostCmpnyNm
FROM TB_TBM_SESSION_SHARE S
     LEFT OUTER JOIN TB_CMPNY C
        ON (
            C.CMPNY_CD = S.DESIGNATED_BY_CMPNY_CD
        )
WHERE S.SHARE_CMPNY_CD = #{shareCmpnyCd}
  AND S.DEL_YN = 'N'
  AND S.SESSION_CD IN

    #{sc}

/* TbmSessionShareMapper.selectCmpnyNm */
SELECT
    C.CMPNY_NM
FROM TB_CMPNY C
WHERE C.CMPNY_CD = #{cmpnyCd}
LIMIT 1

/* TbmSessionShareMapper.selectParentCmpnyNm */
SELECT
    IFNULL(C.CMPNY_NM, '')
FROM TB_TBM_SESSION_SHARE S
     LEFT OUTER JOIN TB_CMPNY C
        ON (
            C.CMPNY_CD = S.DESIGNATED_BY_CMPNY_CD
        )
WHERE S.SESSION_CD = #{sessionCd}
  AND S.SHARE_CMPNY_CD = #{shareCmpnyCd}
  AND S.DEL_YN = 'N'
LIMIT 1

/* TbmSessionShareMapper.selectShareSlot */
SELECT
      S.SHARE_ID    AS shareId
    , S.DEL_YN      AS delYn
FROM TB_TBM_SESSION_SHARE S
WHERE S.SESSION_CD = #{sessionCd}
  AND S.SHARE_CMPNY_CD = #{shareCmpnyCd}
LIMIT 1

mapper.insert:
/* TbmSessionShareMapper.insertShare */
INSERT INTO TB_TBM_SESSION_SHARE (
      SESSION_CD
    , HOST_CMPNY_CD
    , SHARE_CMPNY_CD
    , DESIGNATED_BY_CMPNY_CD
    , DESIGNATED_BY_USER_CD
    , DESIGNATED_DTIME
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{sessionCd}
    , #{hostCmpnyCd}
    , #{shareCmpnyCd}
    , #{designatedByCmpnyCd}
    , #{designatedByUserCd}
    , NOW()
    , 'N'
    , #{designatedByUserCd}
    , NOW()
    , #{designatedByUserCd}
    , NOW()
)

mapper.update:
/* TbmSessionShareMapper.restoreShare */
UPDATE TB_TBM_SESSION_SHARE
SET
      DEL_YN                  = 'N'
    , HOST_CMPNY_CD           = #{hostCmpnyCd}
    , DESIGNATED_BY_CMPNY_CD  = #{designatedByCmpnyCd}
    , DESIGNATED_BY_USER_CD   = #{designatedByUserCd}
    , DESIGNATED_DTIME        = NOW()
    , RELEASE_REASON_CD       = NULL
    , RELEASED_BY_CMPNY_CD    = NULL
    , RELEASED_BY_USER_CD     = NULL
    , RELEASED_DTIME          = NULL
    , UPDATE_NO               = #{designatedByUserCd}
    , UPDATE_DATE             = NOW()
WHERE SESSION_CD = #{sessionCd}
  AND SHARE_CMPNY_CD = #{shareCmpnyCd}
  AND DEL_YN = 'Y'

/* TbmSessionShareMapper.releaseShares */
UPDATE TB_TBM_SESSION_SHARE
SET
      DEL_YN                = 'Y'
    , RELEASE_REASON_CD     = #{releaseReasonCd}
    , RELEASED_BY_CMPNY_CD  = #{releasedByCmpnyCd}
    , RELEASED_BY_USER_CD   = #{releasedByUserCd}
    , RELEASED_DTIME        = NOW()
    , UPDATE_NO             = #{releasedByUserCd}
    , UPDATE_DATE           = NOW()
WHERE SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND SHARE_CMPNY_CD IN

    #{cc}
